script:
// Sign-up form: creates the account straight away (no approval) and signs the customer in.
window.onload = function () {
  if (page_data.user && page_data.user !== "Guest") {
    const urlParams = new URLSearchParams(window.location.search);
    window.location.href = urlParams.get('redirect-to') || '/profile';
  }
};

function registerToast(text, ok) {
  Toastify({
    text: text,
    close: true,
    gravity: "top",
    position: "center",
    stopOnFocus: true,
    style: {
      background: ok ? "linear-gradient(to right, #00b09b, #96c93d)" : "linear-gradient(to right, #ff5f6d, #ffc371)",
    }
  }).showToast();
}

function serverMessage(result) {
  try {
    const messages = JSON.parse(result._server_messages);
    return JSON.parse(messages[0]).message.replace(/<[^>]*>/g, '');
  } catch (e) {
    return "";
  }
}

(function () {
  const showPassword = document.getElementById("show_password");
  const passwordInput = document.getElementById("password");
  const confirmInput = document.getElementById("confirm_password");
  if (showPassword && passwordInput && confirmInput) {
    showPassword.setAttribute("type", "checkbox");
    showPassword.addEventListener("change", function () {
      const type = this.checked ? "text" : "password";
      passwordInput.setAttribute("type", type);
      confirmInput.setAttribute("type", type);
    });
  }
})();

document.getElementById('register_form').addEventListener('submit', async function (e) {
  e.preventDefault();

  const form = e.target;
  const submitBtn = form.querySelector('button[type="submit"]');
  const data = {};
  new FormData(form).forEach((value, key) => { data[key] = value; });

  if ((data.password || "").length < 8) {
    registerToast("Password must be at least 8 characters long.", false);
    return;
  }
  if (data.password !== data.confirm_password) {
    registerToast("Passwords do not match.", false);
    return;
  }

  if (submitBtn) submitBtn.disabled = true;
  try {
    const response = await fetch('/api/method/invento_webshop.api.register.register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-frappe-csrf-token': page_data.csrf_token,
      },
      body: JSON.stringify({ doc: data, cart_items: frappe.get_cookie("cart_items") || "[]" })
    });
    const result = await response.json();

    if (response.ok && result.message) {
      registerToast("Your account has been created. Welcome!", true);
      const redirectTo = new URLSearchParams(window.location.search).get('redirect-to');
      setTimeout(() => { window.location.href = redirectTo || '/profile'; }, 1000);
      return;
    }
    registerToast(serverMessage(result) || "Could not create your account. Please try again.", false);
  } catch (error) {
    console.error('Error:', error);
    registerToast("An error occurred. Please try again.", false);
  }
  if (submitBtn) submitBtn.disabled = false;
});
